-- Search fixture for the api-tester `search` mode (agaia-4886): run by harness/seed-search.sh after
-- prepare-test-db.sh, only before `--mode search`, so the other catalogs' data stays as it is. Two projects
-- of their own and made-up words keep the search cases clear of every other seeded or created issue.
-- Issue numbers 8917 and 9101-9172 are fixed: number cases name them.
BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM issues WHERE "issueNumber" IN (9101, 9102, 9103, 9104, 9105, 9106, 9107, 9108, 9109, 9110, 9111, 9112, 9113, 9114, 9115, 9116, 9117, 9118, 9119, 9120, 9121, 9122, 9123, 9124, 9170, 9171, 9172, 8917)
             AND id NOT LIKE 'api-test-search-%') THEN
    RAISE EXCEPTION 'search fixture: issue numbers 8917 and 9101-9172 already belong to other issues; '
      'seed-search.sql needs a test database freshly prepared by prepare-test-db.sh';
  END IF;
END $$;

INSERT INTO projects (
  id, name, "shortCode", type, "modifiedUser", deleted, status,
  "createdUser", "createdUserName", "modifiedUserName", done, "projectManager"
) VALUES
  ('api-test-search-proj-a', 'Search Alpha', 'SRA', 'software', 'api-test-user-0001', 0, 'in_progress', 'api-test-user-0001', 'API Tester', 'API Tester', 0, 'api-test-user-0001'),
  ('api-test-search-proj-b', 'Search Beta', 'SRB', 'software', 'api-test-user-0001', 0, 'in_progress', 'api-test-user-0001', 'API Tester', 'API Tester', 0, 'api-test-user-0001')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, deleted = 0;

