SELECT setval('"issues_issueNumber_seq"', GREATEST((SELECT MAX("issueNumber") FROM issues), 1));

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_matviews WHERE schemaname = 'auth' AND matviewname = 'accessible_issues') THEN
    REFRESH MATERIALIZED VIEW auth.accessible_issues;
  END IF;
END $$;

